import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const ORIGINAL = 'test';

// Открывает /journey и ждёт, пока загрузится קבלה (строка загрузки исчезла, карточка видна).
async function gotoJourney(page: Page) {
  await page.goto('/journey');
  const card = page.getByRole('button', { name: /^מקבל על עצמי/ });
  await expect(card).toBeVisible({ timeout: 20_000 });
  await expect(page.getByText('טוענים את הקבלה האישית…')).toHaveCount(0, { timeout: 30_000 });
  await dismissMilestoneIfShown(page);
  return card;
}

// Нажимает «שמירה» и ждёт, пока запись в personal_commitments (POST/PATCH/PUT/DELETE) завершится на сервере —
// иначе следующий page.goto обрывает запрос и после reload видно старое значение.
async function saveCommitment(page: Page) {
  const isWrite = (url: string, method: string) =>
    url.includes('/rest/v1/personal_commitments') && ['POST', 'PATCH', 'PUT', 'DELETE'].includes(method);
  let pending = 0;
  let finished = 0;
  const onRequest = (r: import('@playwright/test').Request) => {
    if (isWrite(r.url(), r.method())) pending++;
  };
  const onDone = (r: import('@playwright/test').Request) => {
    if (isWrite(r.url(), r.method())) {
      pending--;
      finished++;
    }
  };
  page.on('request', onRequest);
  page.on('requestfinished', onDone);
  page.on('requestfailed', onDone);
  try {
    const firstWrite = page.waitForResponse((r) => isWrite(r.url(), r.request().method()), { timeout: 20_000 });
    await page.getByRole('button', { name: 'שמירה' }).click();
    const resp = await firstWrite;
    expect(resp.ok(), `personal_commitments ${resp.request().method()} → ${resp.status()}`).toBe(true);
    // Если приложение шлёт несколько запросов подряд (напр. DELETE + POST) — дождаться всех.
    await expect.poll(() => finished > 0 && pending === 0, { timeout: 20_000 }).toBe(true);
  } finally {
    page.off('request', onRequest);
    page.off('requestfinished', onDone);
    page.off('requestfailed', onDone);
  }
}

async function openCommitment(page: Page) {
  await page.getByRole('button', { name: /^מקבל על עצמי/ }).click();
  const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
  await expect(field).toBeVisible();
  await expect(field).toBeEditable();
  return field;
}

test.describe('«המסע שלי»', () => {
  test('JR-04 «מקבל על עצמי» — задать, удалить, вернуть; без фиктивного прогресса #6a86f7fb #31c88137 @data @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    try {
      // 1. `/journey` → дождаться исчезновения «טוענים את הקבלה האישית…» → «מקבל על עצמי» → поле → «QA-AUTO-קבלה» → «שמירה»; reload.
      await gotoJourney(page);
      const field = await openCommitment(page);
      await expect(field).toHaveAttribute('maxlength', '280');
      await expect(field).toHaveAttribute('placeholder', 'מה אני מקבל על עצמי');
      // Поле раскрывается уже с «test» и доступно для ввода
      await expect(field).toHaveValue(ORIGINAL);
      await field.fill('QA-AUTO-קבלה');
      await saveCommitment(page);
      const commitButton = await gotoJourney(page);
      await expect(commitButton).toContainText('QA-AUTO-קבלה');
      // Рядом нет полосы прогресса
      await expect(commitButton.locator('xpath=..').getByRole('progressbar')).toHaveCount(0);

      // 2. Дождаться исчезновения «טוענים את הקבלה האישית…» → «מקבל על עצמי» → «הסרת הקבלה» → «שמירה»; reload.
      await openCommitment(page);
      await page.getByRole('button', { name: 'הסרת הקבלה' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0); // только очищает поле, без окна
      await expect(page.getByRole('textbox', { name: 'מקבל על עצמי' })).toHaveValue('');
      await saveCommitment(page);
      await gotoJourney(page);
      await expect(page.getByText('עדיין לא הגדרת קבלה אישית.')).toBeVisible();
    } finally {
      // 3. Уборка: дождаться исчезновения «טוענים את הקבלה האישית…» → «מקבל על עצמי» → «test» → «שמירה»; reload.
      await gotoJourney(page);
      const field = await openCommitment(page);
      await field.fill(ORIGINAL);
      await saveCommitment(page);
      await gotoJourney(page);
      await expect(page.getByRole('button', { name: /^מקבל על עצמי/ })).toContainText(ORIGINAL);
    }
  });
});
